import React from "react";
import {observer} from 'mobx-react';

import AggregateStat from "components/AggregateStat";

import byLogged from "./Query/List/listAllEmployeeByLogged";

@observer
class AListTab extends React.Component {
    constructor(props) {
        super(props);

        this.onLoadList = this.onLoadList.bind(this);

        this.renderTHead = this.renderTHead.bind(this);
        this.renderItem = this.renderItem.bind(this);
        this.renderPopoverOptions = this.renderPopoverOptions.bind(this);
        this.renderFilterNode = this.renderFilterNode.bind(this);
    }

    //<editor-fold desc="onLoadList">
    onLoadList(params = {}) {
        const {list} = this.props;
        if(list) {
            return this.findByIdsEmployees(list.map(({id}) => id));
        }

        const paramsProps = this.props.params || {};

        params = {...params, ...paramsProps};

        const {page, lastItem, filterData, filtered, isNew} = params;
        const {
            department_id,
            job_position_id,
            team_id,
            supervisor_id,
            name,
            id_or_pass_num,
        } = filterData || {};

        const limit = 50;

        const args = {
            removed: this.removed,
            //
            department_id,
            job_position_id,
            team_id,
            supervisor_id,
            name,
            id_or_pass_num,
            //
            limit,
            //
            exact_orgs: true,
        };

        if(!isNew) {
            args.offset = this.refs.root.list.length;
        } else {
            args.offset = 0;
        }

        return byLogged(args).then((res) => {
            console.log('onLoadList res', res)
            return res;
        });
    }
    //</editor-fold>
    
}

